PRAGMA foreign_keys=OFF;
DELETE FROM "sent_log";
DELETE FROM "messages";
DELETE FROM "folders";
DELETE FROM "drafts";
DELETE FROM "attachments";
DELETE FROM "account_config";
DELETE FROM "_counters";
UPDATE messages
SET body_text = replace(replace(replace(replace(body_text,
  'This message covers', 'This account notice lists'),
  'The household file records', 'Sam marked the item as'),
  'Evidence basis:', 'Document checked:'),
  'follow-up outcome:', 'Current disposition:')
WHERE json_extract(headers_json, '$.thread_class') IN (
  'card_statement_notice', 'electric_bill_notice', 'internet_service_update',
  'mobile_plan_statement', 'water_service_statement', 'subscription_renewal'
);

UPDATE messages
SET body_text = replace(replace(replace(replace(body_text,
  'This message covers', 'Receipt details include'),
  'The household file records', 'The copy in the household folder shows'),
  'Evidence basis:', 'Matched against'),
  'follow-up outcome:', 'Filing result:')
WHERE json_extract(headers_json, '$.thread_class') IN (
  'donation_acknowledgment', 'pharmacy_receipt', 'rent_portal_receipt',
  'travel_receipt', 'grocery_receipt', 'vehicle_service_receipt'
);

UPDATE messages
SET body_text = replace(replace(replace(replace(body_text,
  'This message covers', 'The latest service update concerns'),
  'The household file records', 'The open household note now shows'),
  'Evidence basis:', 'Support came from'),
  'follow-up outcome:', 'Next handling:')
WHERE json_extract(headers_json, '$.thread_class') IN (
  'childcare_invoice', 'home_maintenance_invoice', 'insurance_policy_notice',
  'medical_claim_update', 'student-loan_notice', 'transit_account_message'
);

UPDATE messages
SET body_text = replace(replace(replace(replace(body_text,
  'This message covers', 'Account correspondence covers'),
  'The household file records', 'For month-end, Sam classified it as'),
  'Evidence basis:', 'Reconciled with'),
  'follow-up outcome:', 'Account follow-up:')
WHERE json_extract(headers_json, '$.thread_class') IN (
  'brokerage_statement', 'checking_account_alert', 'community_membership_renewal',
  'payroll_statement', 'tax_payment_reminder', 'savings_account_update'
);
PRAGMA foreign_keys=ON;
